// Ported from the Node app's Sequelize model FeeGroupItem (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class FeeGroupItemConfiguration : IEntityTypeConfiguration<FeeGroupItem>
{
    public void Configure(EntityTypeBuilder<FeeGroupItem> builder)
    {
        builder.ToTable("fee_group_items");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.GroupId).HasColumnName("group_id");
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(120)").HasMaxLength(120).IsRequired();
        builder.Property(e => e.Amount).HasColumnName("amount").HasColumnType("decimal(10,2)");
        builder.Property(e => e.DueDate).HasColumnName("due_date").HasColumnType("date");
        builder.HasOne(e => e.FeeGroup).WithMany(p => p.FeeGroupItems).HasForeignKey(e => e.GroupId).OnDelete(DeleteBehavior.NoAction);
    }
}
